      const fb = createFramebuffer()
      const gs = createInitialGameState({ x: 0, y: 0, facing: 'down' })
      drawMenuStack(fb, gs, distinctUiFrames())
      expect(fb.indices.every((v) => v === 0)).toBe(true)
    })

